public void block(SpellCastEvent event) {
    if (event.getEntity() instanceof Player player && player.hasEffect(ModPotions.HYMN_OF_ORDER))
        event.setCanceled(true);
}

public void punish(MaxManaCalcEvent event) {
    if (event.getEntity() instanceof Player player && player.hasEffect(ModPotions.HYMN_OF_ORDER))
        event.setReserve(1.0F);
}

public static void DeathEvent(LivingDeathEvent event) {

    //when the player dies, if they have the hymn of order effect, save the effect duration to the player's persistent data.
    if (event.getEntity() instanceof Player player && player.hasEffect(ModPotions.HYMN_OF_ORDER)) {
        MobEffectInstance effect = player.getEffect(ModPotions.HYMN_OF_ORDER);
        if (effect == null) return;
        CompoundTag data = player.getPersistentData();
        if (!data.contains(Player.PERSISTED_NBT_TAG)) {
            data.put(Player.PERSISTED_NBT_TAG, new CompoundTag());
        }
        CompoundTag persist = data.getCompound(Player.PERSISTED_NBT_TAG);

        persist.putBoolean("magic_locked", true);
        persist.putInt("magic_lock_duration", effect.getDuration());
    }
}

public static void onPlayerRespawnHW(PlayerEvent.Clone event) {
    if (!event.isWasDeath() || event.getEntity().level().holder(ModRegistry.SOULBOUND).isEmpty()) return;
    CompoundTag data = event.getEntity().getPersistentData();
    //when the player respawns, if they have the hymn of order effect, apply the effect to the player.
    if (data.contains(Player.PERSISTED_NBT_TAG)) {
        CompoundTag persist = data.getCompound(Player.PERSISTED_NBT_TAG);
        if (persist.contains("magic_locked") && persist.contains("magic_lock_duration")) {
            event.getEntity().addEffect(new MobEffectInstance(ModPotions.HYMN_OF_ORDER, persist.getInt("magic_lock_duration")));
            persist.remove("magic_locked");
            persist.remove("magic_lock_duration");
        }

        //when the player respawns, if they have soulbound items, give them back to the player.
        CompoundTag soulTag = persist.getCompound(TAG_SOULBOUND);

        int count = soulTag.getInt(TAG_SOULBOUND_DROP_COUNT);
        List<ItemStack> recovered = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            CompoundTag toRecover = soulTag.getCompound(TAG_SOULBOUND_PREFIX + i);
            ItemStack stack = ItemStack.parseOptional(event.getEntity().registryAccess(), toRecover);
            if (!stack.isEmpty()) {
                recovered.add(stack.copy());
            }
        }

        //try to put the items in the same slots they were in before.
        for (ItemStack stack : recovered) {
            if (stack.getItem() instanceof ArmorItem armor && event.getEntity().getItemBySlot(armor.getType().getSlot()).isEmpty()) {
                event.getEntity().setItemSlot(armor.getType().getSlot(), stack);
            } else if (stack.getItem() instanceof ShieldItem && event.getEntity().getOffhandItem().isEmpty()) {
                event.getEntity().setItemInHand(InteractionHand.OFF_HAND, stack);
            } else {
                ItemHandlerHelper.giveItemToPlayer(event.getEntity(), stack);
            }
        }

        persist.remove(TAG_SOULBOUND);
    }
}

public ArsElemental(IEventBus modEventBus, ModContainer modContainer) {
    terrablenderLoaded = ModList.get().isLoaded("terrablender");
    ENABLE_ENTHRALL = true;
    ENABLE_SPELL_CRIT = true;
    modContainer.registerConfig(ModConfig.Type.STARTUP, ConfigHandler.STARTUP_SPEC);
    modContainer.registerConfig(ModConfig.Type.COMMON, ConfigHandler.COMMON_SPEC);
    modContainer.registerConfig(ModConfig.Type.CLIENT, ConfigHandler.CLIENT_SPEC);
    ModRegistry.registerRegistries(modEventBus);
    ArsNouveauRegistry.init();
    modEventBus.addListener(this::setup);
    modEventBus.addListener(this::loadComplete);
    modEventBus.addListener(this::attachCaps);
    NeoForge.EVENT_BUS.register(ModPotions.class);
    if (FMLEnvironment.dist.isClient()) {
        NeoForge.EVENT_BUS.addListener(new ClientEvents()::openBackpackGui);
        modEventBus.addListener(this::doClientStuff);
    }
    ModAdvTriggers.init();
}

package alexthw.ars_elemental.registry;

import alexthw.ars_elemental.common.mob_effects.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.alchemy.Potion;
import net.minecraft.world.item.alchemy.PotionBrewing;
import net.minecraft.world.item.alchemy.Potions;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.neoforge.event.brewing.RegisterBrewingRecipesEvent;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

import static alexthw.ars_elemental.ArsElemental.MODID;
import static alexthw.ars_elemental.ArsElemental.prefix;
import static com.hollingsworth.arsnouveau.common.lib.LibPotions.longPotion;
import static com.hollingsworth.arsnouveau.common.lib.LibPotions.potion;

public class ModPotions {

    public static final DeferredRegister<MobEffect> EFFECTS = DeferredRegister.create(BuiltInRegistries.MOB_EFFECT, MODID);
    public static final DeferredRegister<Potion> POTIONS = DeferredRegister.create(BuiltInRegistries.POTION, MODID);

    public static final DeferredHolder<MobEffect, MobEffect> MAGIC_FIRE;
    public static final DeferredHolder<MobEffect, MobEffect> FROZEN;

    public static final DeferredHolder<MobEffect, MobEffect> WATER_GRAVE;
    public static final DeferredHolder<MobEffect, MobEffect> MANA_BUBBLE;
    public static final DeferredHolder<MobEffect, MobEffect> ENTHRALLED;
    public static final DeferredHolder<MobEffect, MobEffect> HYMN_OF_ORDER;
    public static final DeferredHolder<MobEffect, LifeLinkEffect> LIFE_LINK;
    public static final DeferredHolder<MobEffect, EnderferenceEffect> ENDERFERENCE;
    public static final DeferredHolder<MobEffect, LightningLureEffect> LIGHTNING_LURE;
    public static final DeferredHolder<MobEffect, RepelEffect> REPEL;
    public static final DeferredHolder<MobEffect, VenomEffect> VENOM;
    public static final DeferredHolder<MobEffect, MobEffect> RUST;
    public static final DeferredHolder<MobEffect, MobEffect> MIST;
    public static final DeferredHolder<MobEffect, MobEffect> ICE_SLIDE;


    public static final DeferredHolder<Potion, Potion> ENDERFERENCE_POTION;
    public static final DeferredHolder<Potion, Potion> LONG_ENDERFERENCE_POTION;

    public static final DeferredHolder<Potion, Potion> SHOCK_POTION;
    public static final DeferredHolder<Potion, Potion> LONG_SHOCK_POTION;


    @SubscribeEvent
    private static void addBrewingRecipes(final RegisterBrewingRecipesEvent event) {
        PotionBrewing.Builder builder = event.getBuilder();

        builder.addMix(Potions.AWKWARD, Items.TWISTING_VINES.asItem(), ENDERFERENCE_POTION);
        builder.addMix(ENDERFERENCE_POTION, Items.GLOWSTONE_DUST, LONG_ENDERFERENCE_POTION);

        builder.addMix(Potions.AWKWARD, ModItems.FLASHING_POD.get().asItem(), SHOCK_POTION);
        builder.addMix(SHOCK_POTION, Items.GLOWSTONE_DUST, LONG_SHOCK_POTION);

    }

    static {
        MAGIC_FIRE = EFFECTS.register("hellfire", MagicFireEffect::new);
        FROZEN = EFFECTS.register("frozen", FrozenEffect::new);
        WATER_GRAVE = EFFECTS.register("watery_grave", WaterGraveEffect::new);
        MANA_BUBBLE = EFFECTS.register("mana_shield", BubbleShieldEffect::new);
        ENTHRALLED = EFFECTS.register("enthralled", EnthrallEffect::new);
        LIFE_LINK = EFFECTS.register("life_link", LifeLinkEffect::new);
        HYMN_OF_ORDER = EFFECTS.register("hymn_of_order", OrderEffect::new);
        ENDERFERENCE = EFFECTS.register("enderference", EnderferenceEffect::new);
        LIGHTNING_LURE = EFFECTS.register("static_charged", LightningLureEffect::new);
        REPEL = EFFECTS.register("repel", RepelEffect::new);
        VENOM = EFFECTS.register("venom", VenomEffect::new);
        ICE_SLIDE = EFFECTS.register("slip_feet", SlipFeetEffect::new);
        MIST = EFFECTS.register("mist", () -> new MistEffect().addAttributeModifier(Attributes.FOLLOW_RANGE, prefix("mist"), -0.75f, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
        RUST = EFFECTS.register("rust", () -> new RustEffect().addAttributeModifier(Attributes.ARMOR, prefix("rust"), -0.15f, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));

        ENDERFERENCE_POTION = POTIONS.register(potion("enderference"), () -> new Potion(new MobEffectInstance(ENDERFERENCE, 400)));
        LONG_ENDERFERENCE_POTION = POTIONS.register(longPotion("enderference"), () -> new Potion(new MobEffectInstance(ENDERFERENCE, 1200)));
        SHOCK_POTION = POTIONS.register(potion("shock"), () -> new Potion(new MobEffectInstance(LIGHTNING_LURE, 600)));
        LONG_SHOCK_POTION = POTIONS.register(longPotion("shock"), () -> new Potion(new MobEffectInstance(LIGHTNING_LURE, 400)));

    }

}

public boolean canCast(LivingEntity entity) {
    // Validate the spell
    List<SpellValidationError> validationErrors = spellValidator.validate(spell.unsafeList());

    if (validationErrors.isEmpty()) {
        // Validation successful. We can check the player's mana now.
        return enoughMana(entity);
    } else {
        // Validation failed, explain why if applicable
        if (!silent && !entity.getCommandSenderWorld().isClientSide) {
            // Sending only the first error to avoid spam
            PortUtil.sendMessageNoSpam(entity, validationErrors.get(0).makeTextComponentExisting());
        }
        return false;
    }
}

protected boolean enoughMana(LivingEntity entity) {
    int totalCost = getResolveCost();
    boolean enoughMana = spellContext.getCaster().enoughMana(totalCost);

    boolean canCast = enoughMana || (entity instanceof Player player && player.isCreative());
    if (!canCast && entity instanceof ServerPlayer serverPlayer && !silent) {
        PortUtil.sendMessageNoSpam(serverPlayer, Component.translatable("ars_nouveau.spell.no_mana"));
        Networking.sendToPlayerClient(new NotEnoughManaPacket(totalCost), serverPlayer);
    }
    return canCast;
}

public SpellCastEvent postEvent() {
    return SpellUtil.postEvent(new SpellCastEvent(spell, spellContext));
}

public boolean onCast(ItemStack stack, Level level) {
    if (canCast(spellContext.getUnwrappedCaster()) && !postEvent().isCanceled()) {
        this.hitResult = null;
        CastResolveType resolveType = castType.onCast(stack, spellContext.getUnwrappedCaster(), level, getCastStats(), spellContext, this);
        if (resolveType == CastResolveType.SUCCESS) {
            expendMana();
        }
        return resolveType.wasSuccess;
    }
    return false;
}

public boolean onCastOnEntity(ItemStack stack, Entity target, InteractionHand hand) {
    if (canCast(spellContext.getUnwrappedCaster()) && !postEvent().isCanceled()) {
        this.hitResult = new EntityHitResult(target);
        CastResolveType resolveType = castType.onCastOnEntity(stack, spellContext.getUnwrappedCaster(), target, hand, getCastStats(), spellContext, this);
        if (resolveType == CastResolveType.SUCCESS) {
            expendMana();
        }
        return resolveType.wasSuccess;
    }
    return false;
}

public boolean onCastOnBlock(BlockHitResult blockRayTraceResult) {
    if (canCast(spellContext.getUnwrappedCaster()) && !postEvent().isCanceled()) {
        this.hitResult = blockRayTraceResult;
        CastResolveType resolveType = castType.onCastOnBlock(blockRayTraceResult, spellContext.getUnwrappedCaster(), getCastStats(), spellContext, this);
        if (resolveType == CastResolveType.SUCCESS) {
            expendMana();
        }
        return resolveType.wasSuccess;
    }
    return false;
}

public boolean onCastOnBlock(UseOnContext context) {
    if (canCast(spellContext.getUnwrappedCaster()) && !postEvent().isCanceled()) {
        this.hitResult = context.hitResult;
        CastResolveType resolveType = castType.onCastOnBlock(context, getCastStats(), spellContext, this);
        if (resolveType == CastResolveType.SUCCESS) {
            expendMana();
        }
        return resolveType.wasSuccess;
    }
    return false;
}
